var a=`0035-barszcz-czerwony`;var i=`world-0035`;var s=`PL`;var n=`eastern-europe`;var r=4;var l=36;var o={en:`Barszcz Czerwony`,ua:`Червоний борщ по-польськи`};var g={en:`A classic dish from Poland, featuring beetroot, bay leaf, borscht beet kvass, parsley. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Польща. Основні складники: буряк, лавровий лист, буряковий квас для борщу, петрушка. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 15 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 15 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:15,i:[[`beetroot`,500,`g`],[`water`,1100,`ml`],[`bay-leaf`,1,`leaf`],[`allspice-berries`,3,`pcs`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:6,i:[[`borscht-beet-kvass`,180,`ml`],[`apple-cider-vinegar`,20,`ml`],[`white-granulated-sugar`,15,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Chill briefly if appropriate, garnish with the listed ingredients and serve at the intended temperature.`,ua:`За потреби недовго охолодіть, прикрасьте зазначеними складниками й подавайте за потрібної температури.`,t:[`garnishing`],m:15,i:[[`parsley`,15,`g`]]}];var m={slug:a,id:i,country:`PL`,region:n,servings:4,minutes:36,title:o,text:g,steps:d};export{s as country,m as default,i as id,l as minutes,n as region,r as servings,a as slug,d as steps,g as text,o as title};